dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "group",
      "label": "Search other phenotype group",
      "type": "input",
      "display": "false"
    }
  ],
  "sections": [
    {
      "section id": "all_pegl",
      "header": "All PEGLs",
      "data point": {
        "type": "api",
        "url": "https://hugeampkpncms.org/rest/data?pageid=egl_241",
        "data type": "csv",
        "data wrapper": [
          0,
          "field_data_points"
        ]
      },
      "pre filters": [
        {
          "field": "Phenotype group",
          "value": "search parameter",
          "parameter": "group",
          "type": "search"
        }
      ],
      "filter width": "sm",
      "filters": [
        {
          "field": "Effector list name",
          "label": "First author last name",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Trait",
          "label": "Trait",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Reference",
          "label": "Reference title",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Curated vs automated",
          "label": "Curation",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Top gene vs multiple genes per locus",
          "label": "Genes per locus",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Scoring system",
          "label": "Scoring system",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "join",
            "field name": "Reference",
            "fields to join": [
              "Title",
              "Citation"
            ],
            "join by": ". "
          },
          {
            "type": "raw",
            "field name": "Effector list name",
            "raw field": "Effector list name"
          },
          {
            "type": "raw",
            "field name": "Trait",
            "raw field": "Trait"
          },
          {
            "type": "raw",
            "field name": "Phenotype group",
            "raw field": "Phenotype group"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "PMID"
          },
          {
            "type": "raw",
            "field name": "Effector Gene List",
            "raw field": "Page ID"
          },
          {
            "type": "raw",
            "field name": "View list",
            "raw field": "Page ID"
          },
          {
            "type": "raw",
            "field name": "Curated vs automated",
            "raw field": "Curated vs automated"
          },
          {
            "type": "raw",
            "field name": "Top gene vs multiple genes per locus",
            "raw field": "Top gene vs multiple genes per locus"
          },
          {
            "type": "raw",
            "field name": "Scoring system",
            "raw field": "Scoring system"
          }
        ],
        "top rows": [
          "Effector list name",
          "Trait",
          "Reference",
          "PMID",
          "View list"
        ],
        "column formatting": {
          "View list": {
            "type": [
              "set parameter"
            ],
            "parameter": "id"
          },
          "PMID": {
            "type": [
              "link"
            ],
            "link to": "https://pubmed.ncbi.nlm.nih.gov/",
            "new tab": "true"
          }
        },
        "features": [
          "List type"
        ],
        "List type": [
          "Curated vs automated",
          "Top gene vs multiple genes per locus",
          "Scoring system"
        ]
      }
    },
    {
      "section id": "single_pegl",
      "header": "Single PEGL",
      "data point": {
        "type": "api",
        "url": "https://hugeampkpncms.org/rest/directcsv?",
        "parameters": [
          "id"
        ],
        "parameters type": "parameters",
        "data type": "csv",
        "data wrapper": [
          0,
          "field_data_points"
        ]
      },
      "search parameters": [
        {
          "parameter": "id",
          "label": "EGL ID",
          "type": "input"
        }
      ],
      "table format": {
        "type": "remote",
        "config wrapper": [
          0,
          "field_data_table_format"
        ]
      },
      "filters": {
        "type": "remote",
        "config wrapper": [
          0,
          "field_filters"
        ]
      },
      "visualizer": {
        "type": "remote",
        "config wrapper": [
          0,
          "field_visualizer_configuration"
        ]
      },
      "section description": {
        "type": "remote",
        "config wrapper": [
          0,
          "body"
        ]
      }
    }
  ]
}
